package main

import (
	"bufio"
	"fmt"
	"os"
)

const (
	K   = 1010
	MOD = 1000000007
)

var dp [K][K]int

func powmod(a, x int) int {
	if x == 0 {
		return 1
	}
	if x%2 == 0 {
		return powmod(int(int64(a)*int64(a)%MOD), x/2)
	}
	return int(int64(a) * int64(powmod(a, x-1)) % MOD)
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var k, va, vb int
	fmt.Fscan(in, &k, &va, &vb)

	den := powmod(va+vb, MOD-2)
	pa := int(int64(va) * int64(den) % MOD)
	pb := int(int64(vb) * int64(den) % MOD)
	one_b := int(int64(pa) * int64(powmod(pb, MOD-2)) % MOD)

	for i := k - 1; i >= 0; i-- {
		for j := k; j >= 1; j-- {
			if i+j >= k {
				dp[i][j] = (i + j + one_b) % MOD
			} else {
				dp[i][j] = int((int64(pa)*int64(dp[i][j+1]) + int64(pb)*int64(dp[i+j][j])) % MOD)
			}
		}
	}
	fmt.Println(dp[0][1])
}

